"""
        Set a bit in a byte to 1 if value is truthy, 0 if not.
    """
def setbit(byte: Any, offset: Any, value: Any) -> object {
    if value {
        return (byte | (1 << offset));
    } else {
        return (byte & ~(1 << offset));
    }
}

